<script setup lang="ts">
import { useEditorReturn } from '~/composables/useEditorReturn'
import { ArrowLeft, Save, Copy, Palette as PaletteIcon } from 'lucide-vue-next'
import { normalizePalette, type Resource, type Palette } from '@qinbian/shared'
const returnTo=useEditorReturn('/resources')
const props=defineProps<{resource:Resource}>(),ctx=useQinbian(),item=ref<Resource>(structuredClone(toRaw(props.resource))),palette=ref<Palette>(normalizePalette(props.resource.data.palette)),name=ref(props.resource.name),description=ref(props.resource.description),saving=ref(false),targetTheme=ref('mine')
async function save(){saving.value=true;try{item.value=await apiFetch<Resource>('/api/resources/'+item.value.id,{method:'PUT',body:{...item.value,name:name.value,description:description.value,data:{palette:palette.value}}});ctx.notify('配色卡已保存')}catch(e){ctx.error(e)}finally{saving.value=false}}
async function clone(){try{const copy=await apiFetch<Resource>('/api/resources/'+item.value.id+'/clone',{method:'POST',body:{themeSetId:'mine'}});navigateTo({path:'/resources/'+copy.id,query:{returnTo:returnTo.value}})}catch(e){ctx.error(e)}}
async function apply(){try{await apiFetch('/api/resources/'+item.value.id+'/apply-palette',{method:'POST',body:{themeSetId:targetTheme.value}});await ctx.refreshThemes();ctx.notify('套组配色已更新；已有稿件保留各自的配色快照')}catch(e){ctx.error(e)}}
</script>
<template><div class="page palette-studio"><header class="page-heading"><div><NuxtLink :to="returnTo" class="text-button"><ArrowLeft :size="14"/>返回</NuxtLink><p class="eyebrow">配色成章 · 留作日用</p><h1>{{item.name}}<span class="title-dot">。</span></h1><p class="page-description">每一色，都有自己的名字与轻重。</p></div><button v-if="item.builtin" class="btn primary" @click="clone"><Copy :size="15"/>编辑副本</button><button v-else class="btn primary" :disabled="saving" @click="save"><Save :size="15"/>保存配色卡</button></header><div class="palette-studio-columns"><section><div class="form-stack"><label>配色卡名称<input v-model="name" :readonly="item.builtin"></label><label>用途说明<textarea v-model="description" :readonly="item.builtin" rows="2"/></label></div><PaletteEditor v-model="palette" :readonly="item.builtin"/></section><aside><h3>配色预览</h3><PaletteSwatches :palette="palette"/><div class="palette-application"><h4>用于主题套组</h4><p class="small muted">新生成的组件会带上这份配色及颜色名称。</p><select v-model="targetTheme" aria-label="应用配色的套组"><option v-for="t in ctx.themes.value.filter(t=>!t.builtin)" :key="t.id" :value="t.id">{{t.name}}</option></select><button class="btn full" @click="apply"><PaletteIcon :size="14"/>应用已保存的配色卡</button></div></aside></div></div></template>
